<script setup lang="ts">
import {ref,onMounted,computed,watch} from 'vue'
import OperationRecovery from './OperationRecovery.vue'
import {ApiError,api,post,type Product,type Movement} from '../api'
const props=defineProps<{products:Product[]}>(),emit=defineEmits<{changed:[]}>()
const snapshotProducts=ref<Product[]|null>(null),catalog=computed(()=>snapshotProducts.value||props.products)
watch(()=>props.products,()=>{snapshotProducts.value=null})
const loading=ref(false)
const tab=ref('count'),error=ref(''),success=ref(''),busy=ref(false),issues=ref<Movement[]>([]),records=ref<{id:string;number:string;reason:string;actor_name:string;created_at:string;lines:{product_name:string;unit:string;expected_quantity:number;counted_quantity:number;difference:number}[]}[]>([])
const countLines=ref<{productId:number;countedQuantity:number;stockVersion:number;expected:number}[]>([]),reason=ref(''),key=ref(crypto.randomUUID())
const uncertain=ref(false),pendingReturn=ref(false),pendingKey=ref('')
const source=ref(''),quantity=ref(1),returnReason=ref(''),returnKey=ref(crypto.randomUUID())
const selected=computed(()=>issues.value.find(i=>i.id===source.value))
async function load(){loading.value=true;try{[issues.value,records.value]=await Promise.all([api<Movement[]>('/inventory/issues'),api<typeof records.value>('/inventory/counts')])}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function rotateReturnKey(){quantity.value=1;returnKey.value=crypto.randomUUID()}
async function reloadCountSnapshot(){if(busy.value||uncertain.value)return;busy.value=true;error.value='';success.value='';try{const latest=await api<Product[]>('/products');snapshotProducts.value=latest;for(const line of countLines.value){const p=latest.find(p=>p.id===line.productId);if(p){line.expected=p.stock;line.stockVersion=p.stock_version}}key.value=crypto.randomUUID();success.value='账面数已更新，请重新核对实盘数量后提交'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
function add(){const p=catalog.value.find(p=>!countLines.value.some(l=>l.productId===p.id));if(p)countLines.value.push({productId:p.id,countedQuantity:p.stock,stockVersion:p.stock_version,expected:p.stock})}
function select(index:number){const line=countLines.value[index],p=catalog.value.find(p=>p.id===line.productId);if(p){line.countedQuantity=p.stock;line.stockVersion=p.stock_version;line.expected=p.stock}}
async function submit(returning=false){if(busy.value)return;pendingReturn.value=returning;busy.value=true;error.value='';success.value='';try{if(returning){if(!source.value)throw new Error('请选择一笔未归还的领用');await post(`/inventory/issues/${source.value}/return`,{quantity:quantity.value,reason:returnReason.value},returnKey.value);source.value='';quantity.value=1;returnReason.value='';returnKey.value=crypto.randomUUID();success.value='领用归还已入库'}else{if(!countLines.value.length)throw new Error('请添加盘点商品');await post('/inventory/counts',{lines:countLines.value.map(({productId,countedQuantity,stockVersion})=>({productId,countedQuantity,stockVersion})),reason:reason.value},key.value);countLines.value=[];reason.value='';key.value=crypto.randomUUID();success.value='盘点已记录，差异已生成库存流水'}uncertain.value=false;emit('changed');await load()}catch(e){error.value=(e as Error).message;if(e instanceof ApiError){uncertain.value=e.uncertain;pendingKey.value=e.key}}finally{busy.value=false}}
async function confirmed(){uncertain.value=false;error.value='';success.value='已确认操作成功，库存和记录已更新';if(pendingReturn.value){source.value='';quantity.value=1;returnReason.value='';returnKey.value=crypto.randomUUID()}else{countLines.value=[];reason.value='';key.value=crypto.randomUUID()}emit('changed');await load()}
defineExpose({reload:load})
onMounted(load)
</script>
<template><section class="panel feature-panel"><div class="filter-tabs"><button v-for="item in [{id:'count',name:'库存盘点'},{id:'return',name:'领用归还'},{id:'history',name:'盘点记录'}]" :key="item.id" :class="{active:tab===item.id}" :disabled="uncertain||busy" @click="tab=item.id;error='';success=''">{{item.name}}</button></div><p v-if="loading" class="form-hint" role="status">正在读取库存记录…</p><button v-if="error" class="btn" :disabled="busy||loading||uncertain" @click="load">重新读取记录</button><p v-if="error" class="form-error" role="alert">{{error}}</p><p v-if="success" class="inline-success" role="status">{{success}}</p><OperationRecovery v-if="uncertain" :request-key="pendingKey" :busy="busy" @committed="confirmed" @retry="submit(pendingReturn)"/><form v-if="tab==='count'" @submit.prevent="submit()"><fieldset :disabled="uncertain||busy" style="border:0;padding:0;margin:0;min-width:0"><p class="form-intro">填写实际清点数量，系统会记录盘盈或盘亏。盘点期间库存发生变化时，本次提交会被拒绝，请刷新后重新核对。</p><div class="table-scroll"><table><thead><tr><th>盘点商品</th><th>账面数量</th><th>实盘数量</th><th>差异</th><th>操作</th></tr></thead><tbody><tr v-for="(line,index) in countLines" :key="index"><td><select v-model="line.productId" :aria-label="'盘点商品 '+(index+1)" @change="select(index)"><option v-for="p in catalog" :key="p.id" :value="p.id" :disabled="countLines.some((l,i)=>i!==index&&l.productId===p.id)">{{p.name}}</option></select></td><td>{{line.expected}}</td><td><input v-model.number="line.countedQuantity" class="quantity-input" :aria-label="'实盘数量 '+(index+1)" type="number" min="0" max="100000000" required/></td><td :class="line.countedQuantity-line.expected<0?'shortage':'positive'">{{line.countedQuantity-line.expected}}</td><td><button type="button" class="text-button" @click="countLines.splice(index,1)">移除</button></td></tr></tbody></table></div><p v-if="!catalog.length" class="form-hint">暂无可盘点商品，请先在商品档案中添加商品。</p><button type="button" class="btn" :disabled="countLines.length>=catalog.length||countLines.length>=100" @click="add">添加盘点商品</button><button type="button" class="btn" :disabled="busy||!countLines.length" @click="reloadCountSnapshot">重新读取账面数</button><label class="field-block">盘点说明<textarea v-model="reason" maxlength="300" rows="2" required placeholder="例如：月末盘点，仓库实物复核"></textarea></label><button class="btn primary" :disabled="busy||!countLines.length">确认盘点并调整差异</button></fieldset></form><form v-else-if="tab==='return'" @submit.prevent="submit(true)"><fieldset :disabled="uncertain||busy" style="border:0;padding:0;margin:0;min-width:0"><p class="form-intro">归还必须关联原领用记录，累计归还不能超过原领用数量。</p><label class="field-block">原领用记录<select v-model="source" required @change="rotateReturnKey"><option value="">请选择未归还的领用</option><option v-for="i in issues" :key="i.id" :value="i.id">{{i.product_name}} · 未归还 {{i.remaining}} {{i.unit}} · {{i.reference}}</option></select></label><label class="field-block">本次归还数量<input v-model.number="quantity" type="number" min="1" :max="selected?.remaining||0" required/></label><label class="field-block">归还说明<input v-model="returnReason" maxlength="100" required placeholder="例如：员工工位调整，归还仓库"/></label><button class="btn primary" :disabled="busy||!source">确认归还入库</button><p v-if="!issues.length&&!loading&&!error" class="small-copy muted">暂无未归还的领用记录。</p></fieldset></form><div v-else><div v-for="record in records" :key="record.id" class="count-record"><div class="section-caption">{{record.number}}<span>{{record.actor_name}} · {{record.created_at.replace('T',' ').slice(0,16)}}</span></div><p class="small-copy muted">{{record.reason}}</p><div class="table-scroll"><table><thead><tr><th>商品</th><th>原账面</th><th>实盘</th><th>差异</th></tr></thead><tbody><tr v-for="(line,index) in record.lines" :key="index"><td>{{line.product_name}}</td><td>{{line.expected_quantity}}</td><td>{{line.counted_quantity}}</td><td>{{line.difference}} {{line.unit}}</td></tr></tbody></table></div></div><div v-if="!records.length&&!loading&&!error" class="empty">暂无盘点记录。</div><p class="small-copy muted">最多展示最近 100 张盘点单。</p></div></section></template>
